1	// Windows薄适配；不修改固定版本官方Skill，也不生成内容或布局。
2	const path = require('path');
3	const { chromium } = require('playwright');
4	const launch = chromium.launch.bind(chromium);
5	chromium.launch = (options = {}) => launch({
6	  ...options,
7	  env: { ...process.env, ...(options.env || {}) },
8	});
9	const official = require(path.resolve(__dirname, '../skills/pptx/scripts/html2pptx.js'));
10	module.exports = (htmlFile, presentation, options) => official(
11	  path.resolve(htmlFile).replace(/\\/g, '/'), presentation, options,
12	);
